export function appendResult(caseName: string, run: ActRun): void {
  const bar = "=".repeat(80);
  const block = [
    bar,
    `TEST CASE: ${caseName}`,
    `act exit code: ${run.exitCode}`,
    bar,
    run.output.trimEnd(),
